  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Narratives of Freedom$j$, $j${"readings": [{"title": "Exodus 3 (King James Version)", "url": "/portal/bible/Exodus/3"}], "body": "Before and during the Civil War, formerly enslaved Americans wrote and spoke to tell the truth about slavery and to call the nation to repent. Frederick Douglass escaped slavery, taught himself to read and became one of the most powerful speakers and writers in America. Harriet Jacobs wrote about her years in hiding and her fight to protect her children. Sojourner Truth traveled the country as a preacher and speaker for freedom and the rights of women.\n\nA narrative is a true or imagined account of events. In a first person narrative, the narrator says I. The narrator's point of view includes what the narrator knows, believes and feels. An author can use contrast to shape that point of view. Contrast places two things side by side: freedom and bondage, hope and fear, silence and speech.\n\nRead this original first person narrative passage, written in the spirit of the freedom narratives:\n\nThey told me I could not learn my letters, but the words found me anyway. In the dark of the cabin I traced them in the dust with one finger. By day I carried water; by night I carried the alphabet. The master owned my hands, but he never owned my mind, and a mind that has tasted reading cannot be locked.\n\nContrast: owned hands against a free mind; day against night; carrying water against carrying the alphabet. Point of view: the narrator is determined, hopeful and dignified.\n\nScripture connection: Luke 4:18 says, The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives. Many freedom writers drew strength from the promise of deliverance.\n\nYour task: (1) Identify two contrasts in the passage. (2) Describe the narrator's point of view. (3) Explain how the contrasts help the reader understand the narrator.\n\nFlorida standards: ELA.11.R.1.3, ELA.11.R.2.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.3, ELA.11.R.2.2", "script": "Listen carefully today, because we are reading some of the most courageous voices in American history. Before and during the Civil War, men and women who had been enslaved wrote and spoke the truth about slavery and called the nation to repent.\n\nFrederick Douglass escaped slavery, taught himself to read, and became one of the most powerful speakers and writers in America. Harriet Jacobs wrote about her years in hiding and her fight to protect her children. Sojourner Truth traveled the country as a preacher and speaker for freedom and for the rights of women.\n\nNow watch this. A narrative is an account of events. In a first person narrative, the narrator says I. The narrator has a point of view, which means what the narrator knows, believes and feels. And authors shape that point of view with contrast. Contrast puts two things side by side, like freedom and bondage, or hope and fear.\n\nLet us read an original passage in that spirit. They told me I could not learn my letters, but the words found me anyway. In the dark of the cabin I traced them in the dust with one finger. By day I carried water; by night I carried the alphabet. The master owned my hands, but he never owned my mind, and a mind that has tasted reading cannot be locked.\n\nSee the contrasts. Owned hands against a free mind. Day against night. Carrying water against carrying the alphabet. And the point of view? The narrator is determined, hopeful and dignified.\n\nScripture was a source of strength. Luke chapter four, verse eighteen says, The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives. Many freedom writers drew courage from that promise.\n\nYour task today. Identify two contrasts. Describe the narrator's point of view. And explain how the contrasts help the reader understand the narrator. Take the four question check when you finish.\n\nTruth, told bravely, breaks chains. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Narratives of Freedom$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Abolitionist Arguments and Moral Appeals$j$, $j${"readings": [{"title": "Isaiah 61 (King James Version)", "url": "/portal/bible/Isaiah/61"}], "body": "Abolitionists were people who worked to end slavery. Their arguments came from conscience, faith and the founding ideals of the nation. Some pointed out that the Declaration of Independence declared all people created equal. Others argued from Scripture that every person is made in God's image. In Genesis 1:27 the Bible says, So God created man in his own image, in the image of God created he him; male and female created he them.\n\nAn argument has: a claim (what the author believes), reasons (why), evidence (facts, examples, quotations) and often a counterargument (an answer to the other side).\n\nTo compare several arguments on one topic, judge:\n1. Is the claim clear?\n2. Is the reasoning sound (does each step follow)?\n3. Is the evidence relevant and strong enough?\n4. Does the author answer the other side fairly?\n\nRead these two original short arguments about a town library for the whole community:\n\nWriter A: The library should open to every family at no cost. A town that teaches its children to read is a town that guards its future. Every dollar spent on books is returned in wisdom.\n\nWriter B: The library should charge a small yearly fee. Free things are often undervalued, and a fee would keep the shelves stocked. Families who cannot pay could receive a free card.\n\nAnalysis: Both writers have clear claims. Writer A relies on a principle (future and wisdom) but offers little evidence. Writer B gives a reason (undervaluing and stocking) and includes a solution for poor families, which answers a counterargument. Writer B is slightly stronger on soundness; Writer A is stronger on moral appeal.\n\nYour task: (1) State each writer's claim. (2) Judge one strength and one weakness of each. (3) Decide which argument is stronger and give two reasons.\n\nFlorida standards: ELA.11.R.2.3, ELA.11.R.2.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.2.3, ELA.11.R.2.4", "script": "Now we study the arguments of the abolitionists, the people who worked to end slavery. Their arguments came from conscience, faith and the ideals of the founding of the nation. Some pointed out that the Declaration of Independence says all people are created equal. Others argued from Scripture that every person is made in the image of God. Genesis chapter one, verse twenty seven says, So God created man in his own image, in the image of God created he him; male and female created he them.\n\nListen, every strong argument has four parts. A claim, which is what the author believes. Reasons, which tell why. Evidence, which means facts, examples and quotations. And very often a counterargument, which is an answer to the other side.\n\nNow watch this. When we compare arguments on one topic, we judge four things. Is the claim clear? Is the reasoning sound, meaning each step follows? Is the evidence relevant and strong enough? And does the author answer the other side fairly?\n\nLet us practice with two original short arguments about a town library. Writer A says the library should open to every family at no cost. A town that teaches its children to read guards its future. Every dollar spent on books is returned in wisdom. Writer B says the library should charge a small yearly fee. Free things are often undervalued, and a fee would keep the shelves stocked. Families who cannot pay could receive a free card.\n\nBoth have clear claims. Writer A relies on a principle, the future and wisdom, but gives little evidence. Writer B gives a reason, undervaluing and stocking, and includes a solution for poor families, which answers a counterargument. Writer B is slightly stronger on soundness. Writer A is stronger on moral appeal.\n\nYour task today. State each writer's claim. Judge one strength and one weakness of each. And decide which argument is stronger and give two reasons. Take the four question check when you finish.\n\nTest every argument fairly, and hold fast to what is true. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Abolitionist Arguments and Moral Appeals$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Lincoln and the Language of a Nation$j$, $j${"readings": [{"title": "Mark 3 (King James Version)", "url": "/portal/bible/Mark/3"}], "body": "Abraham Lincoln was the sixteenth president of the United States and led the nation through the Civil War. His speeches and letters are admired for their clear thought, moral seriousness and careful use of language. In the Gettysburg Address of November 19, 1863, he spoke in fewer than three minutes. In his Second Inaugural Address he called the nation toward healing, with malice toward none and charity for all.\n\nLincoln used techniques such as:\n1. Short, powerful sentences.\n2. Parallelism and repetition.\n3. Biblical language and allusion (a reference to a known text).\n4. Balance: placing similar ideas in equal form.\n\nAn example allusion: In his famous speech of 1858, Lincoln quoted Jesus in Mark 3:25, And if a house be divided against itself, that house cannot stand. Lincoln used the words to warn that a nation divided over slavery could not remain whole.\n\nRead this original passage in a Lincoln like spirit:\n\nWe are not enemies, but neighbors who have quarreled. The wound is deep, and it will not be healed by pride. Let us bind it with patience, wash it with truth, and rest it in mercy.\n\nTechniques: parallelism (bind it, wash it, rest it); contrast (enemies against neighbors); a metaphor (the wound of the nation). Tone: sorrowful yet hopeful.\n\nYour task: (1) Identify two rhetorical techniques and quote them. (2) Describe the tone. (3) Explain how the biblical allusion in Mark 3:25 supported Lincoln's warning.\n\nFlorida standards: ELA.11.R.2.2, ELA.11.R.2.3, ELA.11.R.3.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.2.2, ELA.11.R.2.3, ELA.11.R.3.4", "script": "Now we hear the voice of Abraham Lincoln, the sixteenth president, who led the nation through the Civil War. His speeches are admired for clear thought, moral seriousness and careful words.\n\nOn November nineteenth, eighteen sixty three, he gave the Gettysburg Address in fewer than three minutes. In his Second Inaugural Address he called the nation toward healing, with malice toward none and charity for all.\n\nListen to what he did with language. He used short, powerful sentences. He used parallelism and repetition. He used biblical language and allusion, which means a reference to a known text. And he used balance, which places similar ideas in equal form.\n\nWatch this. In eighteen fifty eight he used the words of Jesus from Mark chapter three, verse twenty five. And if a house be divided against itself, that house cannot stand. Lincoln used those words to warn that a nation divided over slavery could not remain whole. A single line from Scripture carried the whole warning.\n\nLet us read an original passage in this spirit. We are not enemies, but neighbors who have quarreled. The wound is deep, and it will not be healed by pride. Let us bind it with patience, wash it with truth, and rest it in mercy.\n\nThe techniques are parallelism, bind it, wash it, rest it. Contrast, enemies against neighbors. And a metaphor, the wound of the nation. The tone is sorrowful, yet hopeful.\n\nYour task today. Identify two rhetorical techniques and quote them. Describe the tone. And explain how the biblical allusion supported the warning. Take the four question check when you finish.\n\nWords that heal are worth more than words that win. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Lincoln and the Language of a Nation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Comparing Writers from the Same Era$j$, $j${"readings": [{"title": "Proverbs 18 (King James Version)", "url": "/portal/bible/Proverbs/18"}], "body": "Writers living in the same period can treat the same subject in very different ways. To compare authors, study their historical context (the events, beliefs and conditions of their time), their purpose, their audience, their tone and their techniques.\n\nA comparison chart helps:\nTopic: the same subject for both writers.\nPurpose: why each wrote.\nTone: the attitude each shows.\nTechnique: key methods such as imagery, contrast or rhetorical questions.\nContext: how the time and place shaped each writer.\n\nRead these two original passages about the same Civil War era subject, the winter camp:\n\nPassage A, a soldier's letter: The snow is deep and the fire is poor. We sing hymns to keep our spirits up, and I think of your face. Tell the children I am well and that I will come home when the war is done.\n\nPassage B, a newspaper report: The army has settled into winter quarters. Rations are short and many tents are without proper floors. Officers have asked the public for blankets and shoes, and communities are responding with generous gifts.\n\nComparison:\nTopic: winter camp.\nPurpose: A comforts a family; B informs the public and requests help.\nTone: A is tender and hopeful; B is factual and urgent.\nTechnique: A uses personal detail and an intimate address; B uses facts and a call to action.\nContext: both reflect the hardships of a long war but for different readers.\n\nYour task: (1) Name the topic, purpose and tone for each passage. (2) Explain one way their historical context is similar and one way they differ. (3) State which passage would help a historian more and why.\n\nFlorida standards: ELA.11.R.3.3, ELA.11.R.2.4, ELA.11.R.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.3.3, ELA.11.R.2.4, ELA.11.R.1.3", "script": "Now we put two writers side by side. Writers living in the same period can treat the same subject in very different ways. To compare them, we study historical context, purpose, audience, tone and technique. Historical context means the events, beliefs and conditions of their time.\n\nA comparison chart helps. Name the topic. State each writer's purpose. Describe the tone. Name the techniques. And describe the context.\n\nLet us try with two original passages about the same subject, a winter camp during the Civil War.\n\nPassage A is a soldier's letter. The snow is deep and the fire is poor. We sing hymns to keep our spirits up, and I think of your face. Tell the children I am well and that I will come home when the war is done.\n\nPassage B is a newspaper report. The army has settled into winter quarters. Rations are short and many tents are without proper floors. Officers have asked the public for blankets and shoes, and communities are responding with generous gifts.\n\nWatch this. The topic is the same, a winter camp. The purpose is different. Passage A comforts a family. Passage B informs the public and asks for help. The tone is different. A is tender and hopeful. B is factual and urgent. The techniques differ. A uses personal detail and speaks directly to a loved one. B uses facts and a call to action. And the context is similar, because both show the hardships of a long war, but they are written for different readers.\n\nYour task today. Name the topic, purpose and tone for each passage. Explain one way their context is similar and one way it differs. And state which passage would help a historian more and why. Take the four question check when you finish.\n\nGood readers compare carefully, and fair readers judge with patience. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Comparing Writers from the Same Era$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Comparing Two Arguments$j$, $j${"prompt": "Read these two original short arguments and write a comparison of at least 150 words.\n\nWriter A: Our town should build the new school beside the river. The land is flat, the cost is low, and the river will teach children about nature. A school near water is a school near wonder.\n\nWriter B: Our town should build the new school on the hill. The hill is safe from floods, the road to it is already paved, and the view will inspire every student. A school that stays dry is a school that stays open.\n\nIn your comparison: (1) State each writer's claim. (2) Identify the reasons and evidence each uses. (3) Judge the soundness of each argument and name one weakness in each. (4) Decide which argument is stronger and explain why in at least two sentences. (5) Mention one counterargument that Writer A or Writer B should address. (6) Write in complete sentences with a clear opening and conclusion.", "rubric": "100 points. Claims stated: 15 points. Reasons and evidence identified: 20 points. Soundness judged with weaknesses: 25 points. Decision with reasons: 20 points. Counterargument: 10 points. Grammar and organization: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Comparing Two Arguments$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Freedom and Truth$j$, $j${"prompt": "The voices of Douglass, Truth, Jacobs and Lincoln remind us that words can call a nation to do right. Write a post of at least 120 words that (1) explains why the truth matters when a nation faces a hard moral question, (2) describes how courage and faith can help a person speak up for what is right, (3) tells which voice from this unit moved you most and why, and (4) connects your answer to John 8:32, which says, And ye shall know the truth, and the truth shall make you free. Then write a respectful reply of at least 40 words to another student, or answer this question: How can we speak hard truths with kindness? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Freedom and Truth$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Narratives of Freedom$j$, $j${"questions": [{"q": "A first person narrative uses the pronoun:", "options": ["I", "It only", "You only", "They only"]}, {"q": "Contrast means:", "options": ["Repeating the same word", "Using only rhyme", "Listing dates", "Placing two different things side by side"]}, {"q": "Point of view is:", "options": ["The date it was printed", "The length of a book", "What the narrator knows, believes and feels", "The price of a book"]}, {"q": "Frederick Douglass became known as:", "options": ["A president of the Confederacy", "A powerful speaker and writer for freedom", "A sea captain", "A frontier trapper"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Narratives of Freedom$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,1}'::int[], array[$j$First person narrators say I.$j$,$j$Contrast highlights differences.$j$,$j$Point of view includes the narrator's knowledge and feelings.$j$,$j$Douglass escaped slavery and became a leading voice for freedom.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Narratives of Freedom$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Abolitionist Arguments and Moral Appeals$j$, $j${"questions": [{"q": "An abolitionist was a person who:", "options": ["Led an army for the king", "Worked to end slavery", "Sold goods in a market", "Wrote only poetry"]}, {"q": "A counterargument is:", "options": ["An answer to the other side", "A repeated claim", "A title", "A kind of rhyme"]}, {"q": "Sound reasoning means:", "options": ["The argument is long", "Each step follows logically", "The argument has many adjectives", "The argument is loud"]}, {"q": "Genesis 1:27 teaches that people are made:", "options": ["By accident", "From stone", "By law only", "In the image of God"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Abolitionist Arguments and Moral Appeals$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,3}'::int[], array[$j$Abolitionists worked to end slavery.$j$,$j$A counterargument responds to opposing views.$j$,$j$Sound reasoning follows step by step.$j$,$j$Genesis 1:27 says God created man in his own image.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Abolitionist Arguments and Moral Appeals$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Lincoln and the Language of a Nation$j$, $j${"questions": [{"q": "An allusion is:", "options": ["A list of facts", "A reference to a known text or event", "A kind of title", "A type of rhyme"]}, {"q": "Lincoln gave the Gettysburg Address in:", "options": ["Three hours", "One whole week", "Three days", "Less than three minutes"]}, {"q": "In Mark 3:25 the Bible says a house divided against itself:", "options": ["Will always grow", "Will be rich", "Will win", "Cannot stand"]}, {"q": "Parallelism is:", "options": ["Using no verbs", "Using a different language", "Using similar grammatical form in a series", "Using only questions"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Lincoln and the Language of a Nation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,3,2}'::int[], array[$j$An allusion refers to something well known.$j$,$j$It was a very short speech.$j$,$j$Mark 3:25 says that house cannot stand.$j$,$j$Parallelism repeats a pattern.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Lincoln and the Language of a Nation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Comparing Writers from the Same Era$j$, $j${"questions": [{"q": "Historical context means:", "options": ["The color of the cover", "The number of pages", "The events, beliefs and conditions of the time", "The size of the print"]}, {"q": "A newspaper report in the passage mainly aims to:", "options": ["Frighten children", "Praise the weather", "Tell a joke", "Inform the public and ask for help"]}, {"q": "Tone is:", "options": ["The number of characters", "The date of the text", "The length of the text", "The attitude of the writer"]}, {"q": "When two authors write on the same topic, a good reader compares their:", "options": ["Only page numbers", "Purpose, tone and technique", "Only titles", "Only first words"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Comparing Writers from the Same Era$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,3,1}'::int[], array[$j$Context is the setting of the time period.$j$,$j$The report informs and requests aid.$j$,$j$Tone is the writer's attitude.$j$,$j$Compare purpose, tone and technique.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Comparing Writers from the Same Era$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Slavery, Freedom and the Civil War Voices$j$, $j${"questions": [{"q": "Contrast in a narrative is used to:", "options": ["Hide the narrator", "Highlight differences and shape the reader's understanding", "Fill space", "Replace a title"]}, {"q": "A counterargument:", "options": ["Names the author", "Repeats the claim", "Answers the other side", "Lists dates"]}, {"q": "An allusion is:", "options": ["A reference to a known text or event", "A kind of verb", "A date", "A type of poem"]}, {"q": "Lincoln quoted which verse about a house divided?", "options": ["Genesis 1:1", "Mark 3:25", "Psalm 23:1", "Romans 8:28"]}, {"q": "A first person narrator uses:", "options": ["I", "He only", "It only", "They only"]}, {"q": "Historical context includes:", "options": ["Events and conditions of the time", "Only the title", "The cover art", "Only the author's name"]}, {"q": "Strong evidence is:", "options": ["Loud", "Always long", "Always a quotation", "Relevant and enough to support the claim"]}, {"q": "John 8:32 says that the truth shall:", "options": ["Make you tired", "Make you proud", "Make you quiet", "Make you free"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Slavery, Freedom and the Civil War Voices$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,1,0,0,3,3}'::int[], array[$j$Contrast highlights differences.$j$,$j$It responds to opposing views.$j$,$j$Allusions point to well known works.$j$,$j$Mark 3:25 says a house divided against itself cannot stand.$j$,$j$First person uses I.$j$,$j$Context is the surrounding world of the text.$j$,$j$Evidence must be relevant and sufficient.$j$,$j$John 8:32 says ye shall know the truth, and the truth shall make you free.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Slavery, Freedom and the Civil War Voices$j$ on conflict (item_id) do nothing;
